import{z as A,x as B,o as i,c as p,q as t,j as l,D as E,d as r,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"社会偏好与公平","description":"","frontmatter":{"title":"社会偏好与公平","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/social-preferences.md","filePath":"econ/social-preferences.md","lastUpdated":1791063341000}'),d={name:"econ/social-preferences.md"};function m(c,a,h,u,f,T){const n=B("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="社会偏好与公平" tabindex="-1">社会偏好与公平 <a class="header-anchor" href="#社会偏好与公平" aria-label="Permalink to &quot;社会偏好与公平&quot;">​</a></h1><div class="epigraph"><p>最后通牒里正的拒绝率说明：支付里可以含别人的份额，钱不是唯一参数。</p><footer>—— Güth, Schmittberger and Schwarze, 1982；Fehr and Schmidt, QJE 1999；Rabin, AER 1993</footer></div><p><a href="/econ/bounded-rationality-satisficing">上一课</a>改程序。本课缺口是目标：即使算得完，人也可能拒绝不公平的正金额。不重写满意。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准私人支付 \\(u(x_i)\\) 预测最后通牒博弈接受任何正报价。实验里低报价被拒，提议集中在 40–50%。独裁者博弈仍有正给予。Fehr 与 Schmidt（1999）用不平等厌恶：效用惩罚自己过多与过少。Rabin（1993）用意图：同样的物质结果，善意与恶意得到不同互惠。缺口是在已有<a href="/econ/preference-choice">偏好</a>上把 \\(X\\) 扩成配置，而不是再推独立性。</p><p>家庭金融接口弱而真实：家族保险、遗赠的公平规范、对「市场公平价格」的抵制。本课不把这些写成定价模型。</p><p><span class="marginnote">术语翻译：不平等厌恶不是说「见不得别人有钱」，而是效用里多了一项惩罚——双方所得差距越大，自己的效用被扣得越多。可以把它想象成工资条旁边附了一张「相对收入罚款单」。</span></p><p><span class="marginnote">常见误区：拒绝正报价并非「不理性」。理性只要求按自己的效用最大化；当效用里含公平项时，拒绝恰恰是最优选择。错的是把效用默认成只装钱——装了什么，理性就朝什么方向算。</span></p><p><span class="marginnote">最后通牒拒绝是有代价的惩罚，区别于廉价的公平表态。策略性公平（为了声誉）与内在公平要靠匿名与一次性设计分开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验博弈：最后通牒、独裁者、公共物品、信任博弈。理论：FS 不平等厌恶、Rabin 互惠、Charness–Rabin 的社会偏好一般式。本课只钉「支付可以依赖别人的支付与意图」，不比较哪一套拟合最好。</p>',11)),(i(),l(o,null,{default:E(()=>[s(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRIV%5B%22%E7%A7%81%E4%BA%BA%20u(x_i)%22%5D%20--%3E%20ULT%5B%22%E6%9C%80%E5%90%8E%E9%80%9A%E7%89%92%3A%20%E6%AD%A3%E6%8A%A5%E4%BB%B7%E8%A2%AB%E6%8B%92%22%5D%0A%20%20ULT%20--%3E%20FS%5B%22%E4%B8%8D%E5%B9%B3%E7%AD%89%E5%8E%8C%E6%81%B6%22%5D%0A%20%20ULT%20--%3E%20RAB%5B%22%E6%84%8F%E5%9B%BE%E4%BA%92%E6%83%A0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制是配置进入偏好。拒绝低报价提高相对公平，牺牲绝对货币。这与损失厌恶不同：参考点可以是平等分割，不公平被编码为损失。也可以没有拐折，直接是 \\(u(x_i,x_j)\\)。市场里若匿名竞争足够强，社会偏好可能被价格挤出（市场实验里的收敛）；双边谈判里它留下来。行为金融后段的噪声交易者不必是公平偏好，本课不要混。",-1)),a[5]||(a[5]=e("p",null,"最后通牒的拒绝用私人支付无法解释：正的钱被扔掉，为的是惩罚不公平。FS 把不平等写成自己相对别人过多过少的线性惩罚；Rabin 把同样的物质结果按「对方是否善意」分叉。独裁者仍给，说明不只是策略性恐惧报复。家庭遗赠的公平规范、对涨价的愤怒，可以用同一零件，但加总到资产价格没有识别——噪声交易者课用的是错误信念与风险，不是 \\(\\alpha\\) 嫉妒。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"数字实例：总额 10 元、自己分得 1 元、\\(\\alpha=0.5\\) 时，FS 效用约为 \\(1 - 0.5 \\times (9-1) = -3\\)，为负，于是拒绝——「有代价的惩罚」的算术版。若 \\(\\alpha=0.1\\)，效用为 \\(1-0.8=0.2\\)，为正，低报价反而被接受：拒绝率随人群敏感度而变。")],-1)),(i(),l(o,null,{default:E(()=>[s(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFFER%5B%22%E6%94%B6%E5%88%B0%E6%8A%A5%E4%BB%B7%EF%BC%9A%E6%80%BB%E9%A2%9D%2010%20%E4%B8%AD%E5%88%86%E5%BE%97%201%22%5D%20--%3E%20MAT%5B%22%E7%89%A9%E8%B4%A8%E6%94%B6%E7%9B%8A%EF%BC%9A%E5%BE%97%201%22%5D%0A%20%20OFFER%20--%3E%20GAP%5B%22%E6%AF%94%E8%BE%83%E5%8F%8C%E6%96%B9%E6%89%80%E5%BE%97%EF%BC%9A%E5%B7%AE%208%22%5D%0A%20%20GAP%20--%3E%20PEN%5B%22%E6%89%A3%E4%B8%8D%E5%B9%B3%E7%AD%89%E6%83%A9%E7%BD%9A%EF%BC%9A0.5%20%C3%97%208%20%3D%204%22%5D%0A%20%20MAT%20--%3E%20TOT%7B%22%E6%80%BB%E6%95%88%E7%94%A8%201%20-%204%20%E8%BF%98%E6%98%AF%E6%AD%A3%E7%9A%84%E5%90%97%EF%BC%9F%22%7D%0A%20%20PEN%20--%3E%20TOT%0A%20%20TOT%20--%20%22%E6%98%AF%22%20--%3E%20ACC%5B%22%E6%8E%A5%E5%8F%97%22%5D%0A%20%20TOT%20--%20%22%E5%90%A6%22%20--%3E%20REJ%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E8%8A%B1%E8%87%AA%E5%B7%B1%E7%9A%84%E9%92%B1%E4%B9%B0%E5%85%AC%E5%B9%B3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>利害增大时拒绝率下降但仍非零。跨文化差异大。把实验室公平直接写进资产定价没有识别。本课也不处理政治上的再分配偏好作为宏观主干——那是另一门课。</p><p>后课默认：助推可以利用公平规范（能源账单上的邻居比较），那是选择架构，不是把 FS 效用写进欧拉。</p><p>最后通牒拒绝正金额，私人 \\(u(x_i)\\) 不够；配置与意图进入偏好。</p><p>匿名竞争可挤出公平，双边与家庭内部留得住。噪声交易者不要写成嫉妒。</p><p><span class="marginnote">实验室公平不直接写进资产定价核；加总识别在噪声交易者课另做。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>社会偏好把别人的支付与意图写进 \\(u\\)，解释有代价的拒绝。</li><li>与有限理性分工：目标变了，不是没算完。</li><li>匿名市场可能挤出公平；双边与家庭内部留得住。</li><li>独裁者仍给，说明不只是怕报复。</li><li>利害增大时拒绝率下降，但通常非零。</li><li>出处：Güth et al. 1982；Rabin, <em>AER</em> 1993；Fehr and Schmidt, <em>QJE</em> 1999。</li></ul>',8))])}const F=A(d,[["render",m]]);export{_ as __pageData,F as default};
